use vstd::prelude::*;

verus! {

fn concat(a: &[i32], b: &[i32]) -> (res: Vec<i32>)
    ensures
        res@.len() == a@.len() + b@.len(),
        forall|i: int| 0 <= i < a@.len() ==> res@[i] == a@[i],
        forall|j: int| 0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<i32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a@.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }

    let a_len = a.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j <= b@.len(),
            res@.len() == a@.len() + j as int,
            forall|k: int| 0 <= k < a@.len() ==> res@[k] == a@[k],
            forall|k: int| 0 <= k < j as int ==> res@[a@.len() + k] == b@[k],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }

    // (Optional) connect the runtime `a_len` with the spec `a@.len()` for any needed reasoning.
    assert(a_len as int == a@.len());

    res
}

} // verus!

